<?php
defined('BASEPATH') OR exit('No direct script access allowed');
class Laporan extends MY_Controller { public function index(){ $this->require_login(array('super_admin','tu','kepala'));$this->db->select('alumni.*, jurusan.name jurusan, tahun_lulus.name tahun, status_alumni.name status')->join('jurusan','jurusan.id=alumni.jurusan_id','left')->join('tahun_lulus','tahun_lulus.id=alumni.tahun_lulus_id','left')->join('status_alumni','status_alumni.id=alumni.status_alumni_id','left');if($this->input->get('tahun'))$this->db->where('tahun_lulus_id',(int)$this->input->get('tahun'));$this->render('laporan/index',array('title'=>'Laporan Alumni','items'=>$this->db->get('alumni')->result_array(),'years'=>$this->db->order_by('name','DESC')->get('tahun_lulus')->result_array()));} }
